CREATE POLICY "Users read own activity pictures" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'activity-pictures' AND auth.uid()::text = (storage.foldername(name))[1]);
CREATE POLICY "Users upload own activity pictures" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'activity-pictures' AND auth.uid()::text = (storage.foldername(name))[1]);
CREATE POLICY "Users update own activity pictures" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'activity-pictures' AND auth.uid()::text = (storage.foldername(name))[1]);
CREATE POLICY "Users delete own activity pictures" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'activity-pictures' AND auth.uid()::text = (storage.foldername(name))[1]);